def _run(args,timeout=20):
    r=subprocess.run(args,capture_output=True,text=True,timeout=timeout)
    if r.returncode: raise RuntimeError(f"{args!r}: {r.returncode}: {r.stderr}")
    return r.stdout


def _sha(path):
    h=hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda:f.read(1<<20),b""): h.update(block)
    return h.hexdigest()


def _physical(path):
    if not path.is_absolute() or path.resolve(strict=False)!=path or not path.is_relative_to(B): raise RuntimeError(f"path escaped physical B: {path}")
    return path


def _write(path,value):
    raw=(json.dumps(value,indent=2,sort_keys=True,allow_nan=False)+"\n").encode()
    with path.open("xb") as f: f.write(raw); f.flush(); os.fsync(f.fileno())


def _unit(unit,fields):
    args=["systemctl","--user","show","--all",unit]
    args.extend(part for field in fields for part in ("-p",field))
    return dict(line.split("=",1) for line in _run(args).splitlines())


