def _gpu():
    prefix=["nvidia-smi","-i",GPU]
    status=_run(prefix+["--query-gpu=uuid,name,memory.free,memory.total","--format=csv,noheader"])
    cols=[x.strip() for x in status.strip().split(",")]
    if len(cols)!=4 or cols[0]!=GPU or int(cols[2].split()[0])*1024*1024<MIN_GPU_FREE: raise RuntimeError("selected GPU identity/free reserve failed")
    out=_run(prefix+["--query-compute-apps=pid,gpu_uuid,used_memory","--format=csv,noheader"]); kept=[]
    for row in out.splitlines():
        c=[x.strip() for x in row.split(",")]
        if row.strip().startswith("No running processes found"): continue
        if len(c)!=3 or c[1]!=GPU: raise RuntimeError("unexpected selected-GPU process row")
        proc=Path("/proc")/c[0]
        try: owner=(proc/"cgroup").read_text().strip(); uid=proc.stat().st_uid; cmd=(proc/"cmdline").read_bytes().decode(errors="replace")
        except FileNotFoundError: kept.append({"pid":c[0],"exited_during_observation":True}); continue
        if "wnn-campaign.slice" in owner or (uid==os.getuid() and str(B) in cmd): raise RuntimeError(f"selected GPU owned by another campaign process: {c[0]}")
        kept.append({"pid":c[0],"uid":uid,"cgroup":owner,"used_memory":c[2],"preserved":True})
    return status.strip(),kept


