    expected={item["path"] for item in manifest["files"]}; actual=set()
    for item in manifest["files"]:
        path=SOURCE/item["path"]
        if path.is_symlink() or not path.is_file() or path.stat().st_size!=item["bytes"] or _sha(path)!=item["sha256"]: raise RuntimeError(f"source differs from manifest: {item['path']}")
        actual.add(item["path"])
    existing={x.relative_to(SOURCE).as_posix() for x in SOURCE.rglob("*") if x.is_file() or x.is_symlink()}
    if actual!=expected or existing!=expected or SOURCE.is_symlink() or not SOURCE.is_dir(): raise RuntimeError("staged source inventory is incomplete, extra, or unsafe")
    return len(actual)


